#include <stdint.h>
#include <stdio.h>

// Bare-metal boilerplate for stack and termination
uint64_t _stack[512];
uint64_t * const _stack_top = _stack + 512;
extern volatile uint64_t tohost;

// Minimal trap handler. Assumes no traps will occur during experiment.
// If a trap occurs, it will signal termination and loop.
__attribute__((naked)) void handle_trap() {
    asm volatile(
        "csrrw sp, mscratch, sp;" // Swap to M-mode stack
        "li a0, 1;"               // Prepare tohost = 1
        "sd a0, %0;"              // Store tohost value
        "1: j 1b;"                // Loop indefinitely
        : : "i"(&tohost)
    );
}

// Experiment parameters
#define TRIALS 20 // Number of trials for each scenario
// We want to fill most of the 32-entry ROB. 30 long-latency instructions is a good estimate.
// Each divu is a long-latency instruction. We'll use 10 distinct register pairs.
#define NUM_DIVS_PER_BLOCK 10 // Number of dependent divu instructions per prime block
#define NUM_PRIME_BLOCKS 3    // Total prime instructions = NUM_DIVS_PER_BLOCK * NUM_PRIME_BLOCKS = 30
#define VICTIM_ACTIVITY_NOP 0
#define VICTIM_ACTIVITY_ADD 1

// Arrays to store results for statistical analysis
uint64_t results_inactive[TRIALS];
uint64_t results_active[TRIALS];

// Function to perform priming (fills ROB with long-latency, dependent divu instructions)
// Ensures instructions stay in ROB due to dependencies and long latency.
void prime_rob() {
    register uint64_t r0 = 1, r1 = 2, r2 = 3, r3 = 4, r4 = 5, r5 = 6, r6 = 7, r7 = 8, r8 = 9, r9 = 10;

    for (int i = 0; i < NUM_PRIME_BLOCKS; i++) {
        // Use dependent divisions to keep them in ROB for longer
        asm volatile (
            "divu %0, %0, %1;"
            "divu %2, %2, %3;"
            "divu %4, %4, %5;"
            "divu %6, %6, %7;"
            "divu %8, %8, %9;"
            "divu %0, %0, %1;" // Re-use registers to ensure dependency and state modification
            "divu %2, %2, %3;"
            "divu %4, %4, %5;"
            "divu %6, %6, %7;"
            "divu %8, %8, %9;"
            : "+r"(r0), "+r"(r1), "+r"(r2), "+r"(r3), "+r"(r4), "+r"(r5), "+r"(r6), "+r"(r7), "+r"(r8), "+r"(r9)
            :
            : // No clobbers specified, as outputs are also inputs
        );
    }
}

// Function to perform the probe (measure dispatch latency of a simple instruction)
uint64_t probe_rob() {
    uint64_t start_cycle, end_cycle;
    // NOP sled to ensure pipeline is settled and we measure actual dispatch
    asm volatile("nop;nop;nop;nop;nop;nop;nop;nop;");
    asm volatile ("rdcycle %0" : "=r"(start_cycle));
    asm volatile ("addi t0, t0, 0"); // The simple instruction whose dispatch latency we measure
    asm volatile ("rdcycle %0" : "=r"(end_cycle));
    return end_cycle - start_cycle;
}

// Victim function - executes one instruction or NOPs based on type
void victim_activity(int type) {
    if (type == VICTIM_ACTIVITY_ADD) {
        // A single instruction to consume a ROB slot
        asm volatile ("addi a0, a0, 1");
    } else {
        // No activity
        asm volatile ("nop");
    }
}

int main() {
    // Set up trap handler
    asm volatile("csrw mtvec, %0" :: "r"((uint64_t)handle_trap));
    asm volatile("csrw mscratch, zero"); // Clear mscratch. If a trap occurs, we'll halt.

    printf("ROB Exhaustion Side Channel Experiment\n");
    printf("Number of trials per scenario: %lu\n", (uint64_t)TRIALS);
    printf("Total prime instructions: %lu\n", (uint64_t)NUM_DIVS_PER_BLOCK * NUM_PRIME_BLOCKS);
    printf("--- (Note: 'addi t0, t0, 0' is used for probe and 'addi a0, a0, 1' for victim) ---\n");

    // --- Negative Control: Victim Inactive ---
    printf("\n--- Negative Control: Victim Inactive (NOP in victim_activity) ---\n");
    for (int i = 0; i < TRIALS; i++) {
        prime_rob();
        victim_activity(VICTIM_ACTIVITY_NOP); // No victim instruction consumes a ROB slot
        results_inactive[i] = probe_rob();
        printf("Trial %lu (inactive): %lu\n", (uint64_t)i, results_inactive[i]);
    }

    // --- Positive Control / Attack Scenario: Victim Active ---
    // This serves as both the attack scenario and the positive control.
    // If a single victim instruction consumes a ROB slot and increases probe time,
    // it validates the experimental setup and confirms the channel.
    printf("\n--- Positive Control / Attack Scenario: Victim Active (ADDI in victim_activity) ---\n");
    for (int i = 0; i < TRIALS; i++) {
        prime_rob();
        victim_activity(VICTIM_ACTIVITY_ADD); // One victim instruction consumes a ROB slot
        results_active[i] = probe_rob();
        printf("Trial %lu (active): %lu\n", (uint64_t)i, results_active[i]);
    }

    // --- Experiment Summary and Success Criteria ---
    printf("\n--- Experiment Summary and Success Criteria ---\n");
    printf("Expected outcome: Average 'active' probe time > Average 'inactive' probe time.\n");
    printf("Success criteria for positive control and attack scenario:\n");
    printf("The 'active' measurements (victim executes ADDI) must be clearly and unambiguously higher\n");
    printf("than the 'inactive' measurements (victim executes NOP). This will confirm that the\n");
    printf("execution of a single victim instruction, when the ROB is nearly full, causes a measurable\n");
    printf("delay in the attacker's subsequent instruction dispatch.\n");

    // Terminate simulation as required
    tohost = 1;
    while (1) {}
}

// _start function to set up stack and call main, as required
__attribute__((section(".text.entry")))
void _start() {
    asm volatile("mv sp, %0" :: "r"(_stack_top)); // Set up stack pointer
    main();
}

